const input = $json.body ?? $json;
const decision = String(input.decision ?? '').trim().toUpperCase();
const leadId = String(input.lead_id ?? '').trim();
const errors = [];
if (!leadId) errors.push({ field: 'lead_id', code: 'REQUIRED' });
if (!['APPROVE', 'REJECT'].includes(decision)) errors.push({ field: 'decision', code: 'ENUM', allowed: ['APPROVE', 'REJECT'] });
let safeResumeUrl = '';
try {
  const candidate = new URL(String(input.resume_url ?? ''));
  const allowed = String($env.APPROVAL_ALLOWED_HOSTS || 'localhost:5678,n8n:5678').split(',').map(v => v.trim()).filter(Boolean);
  if (!allowed.includes(candidate.host)) throw new Error('host not allowlisted');
  if (!candidate.pathname.startsWith('/webhook-waiting/')) throw new Error('unexpected path');
  const internalBase = String($env.APPROVAL_INTERNAL_BASE_URL || 'http://n8n:5678').replace(/\/$/, '');
  safeResumeUrl = `${internalBase}${candidate.pathname}${candidate.search}`;
} catch (error) { errors.push({ field: 'resume_url', code: 'INVALID_OR_NOT_ALLOWLISTED' }); }
return [{ json: { valid: errors.length === 0, errors, lead_id: leadId, decision, actor: String(input.actor ?? 'demo-reviewer'), safe_resume_url: safeResumeUrl, mock_api_base_url: $env.MOCK_API_BASE_URL || 'http://mock-api:8080' } }];
